input.command:
ls -la tmp/ledger-pass/ | head -40; python3 -c "
import json
for f in ['pilot.json','runs.json','reconcile.json']:
    d=json.load(open('tmp/ledger-pass/'+f))
    print('==',f, list(d.keys()) if isinstance(d,dict) else type(d))
    runs=d.get('runs',[])
    for r in runs:
        a=r if 'chunks' in r else r.get('args',r)
        ch=a.get('chunks',[])
        print(' ', a.get('name'), a.get('out'), len(ch),'chunks', sum(len(c['rows']) for c in ch),'rows', {k:v for k,v in r.items() if k not in ('chunks','args')} if 'chunks' not in r else {k:v for k,v in a.items() if k not in ('chunks',)})
    for k in d:
        if k!='runs': print('  key',k, str(d[k])[:300])
"

